function c(t){const e=t.replace(/\D/g,"");if(e.length!==11||/^(\d)\1{10}$/.test(e))return"CPF inválido.";const r=(s,a)=>{let o=0;for(let i=0;i<a;i++)o+=parseInt(s[i])*(a+1-i);const n=o*10%11;return n===10||n===11?0:n};if(r(e,9)!==parseInt(e[9])||r(e,10)!==parseInt(e[10]))return"CPF inválido."}function d(t){const e=t.replace(/\D/g,"");if(e.length!==11||/^(\d)\1{10}$/.test(e))return"CNH inválida."}function l(t){const e=t.replace(/[\s.\-/]/g,"");if(!e)return"RG é obrigatório.";if(!/^[a-zA-Z0-9]+$/.test(e))return"RG deve conter apenas caracteres alfanuméricos.";if(e.length<7||e.length>12)return"RG deve ter entre 7 e 12 caracteres."}function u(t){if(!t)return"Data de nascimento é obrigatória.";const e=new Date(t);if(isNaN(e.getTime()))return"Data de nascimento inválida.";const r=new Date().toISOString().split("T")[0];if(t>=r)return"Data de nascimento deve ser no passado."}function f(t){if(!t.trim())return"Nome completo é obrigatório.";if(t.length>255)return"Nome completo deve ter no máximo 255 caracteres."}export{d as a,c as b,f as c,l as d,u as v};
